def validate_winn3_protocol_params(params: Any) -> dict:
    """Normalize and validate a winn/3 protocol_params blob, or raise.

    This is the validator the node-registration path explicitly declined to
    write ("Writing that validator is Winn Protocol v3 design work", see
    register_node). It runs on the WRITE path -- POST /admin/nodes/winn3 --
    so that a malformed advertisement is one 400 to one operator instead of a
    refused connection for every client that node ever serves.

    Returns a dict with lowercase keys and string values, ready to be stored
    as protocol_params_json and handed to the client verbatim. Every rule is
    the client's rule; see the citation on each check.
    """
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise Winn3ContractError("params-not-an-object")

    # The client compares k.toString().trim().toLowerCase() against the
    # allowlist (:1067-1070), so a key that differs only in case is a DIFFERENT
    # key to storage and the SAME key to the sweep. Normalize, and refuse a
    # collision rather than pick a winner.
    normalized: dict = {}
    for raw_key, raw_value in params.items():
        key = str(raw_key or "").strip().lower()
        if not key:
            raise Winn3ContractError("blank-param-name")
        if key in normalized:
            raise Winn3ContractError("duplicate-param-after-normalization", [key])
        if isinstance(raw_value, bool):
            raise Winn3ContractError("param-not-a-scalar", [key])
        if isinstance(raw_value, (dict, list)):
            raise Winn3ContractError("param-not-a-scalar", [key])
        normalized[key] = "" if raw_value is None else str(raw_value).strip()

    unknown = [k for k in normalized if k not in WINN3_KNOWN_PROTOCOL_PARAMS]
    if unknown:
        # The client refuses the whole connection on any of these (:1071-1081).
        # h1..h4 land here, which is correct: obfuscation owns them (:255-258).
        raise Winn3ContractError("unknown-params", unknown)

    # gateway_endpoint (:1084-1099). Optional: absent means the client falls
    # back to vpn_config.server_endpoint, which is the node's own AWG endpoint.
    endpoint = normalized.get("gateway_endpoint", "")
    if endpoint and not winn3_is_ip_literal_endpoint(endpoint):
        raise Winn3ContractError("gateway-endpoint-not-ip-literal", ["gateway_endpoint"])

    # max_datagram (:1104-1119).
    max_datagram = _winn3_int_param(normalized, "max_datagram")
    if max_datagram is not None and not (
        WINN3_MIN_DATAGRAM <= max_datagram <= WINN3_MAX_DATAGRAM
    ):
        raise Winn3ContractError("max-datagram-out-of-range", ["max_datagram"])

    # session_id (:1121-1142). The forbidden characters are the ones that
    # would forge an extra INI key or a section header.
    session_id = normalized.get("session_id", "")
    if len(session_id.encode("utf-8")) > WINN3_MAX_SESSION_ID_BYTES:
        raise Winn3ContractError("session-id-too-long", ["session_id"])
    if any(ch in session_id for ch in ("\n", "\r", "[", "]")):
        raise Winn3ContractError("session-id-malformed", ["session_id"])

    # carrier (:1183-1206). Absent normalizes to direct-awg (:1194-1195).
    carrier = normalized.get("carrier", "").lower()
    resolved_carrier = carrier or WINN3_CARRIER_DIRECT_AWG
    if resolved_carrier not in WINN3_SUPPORTED_CARRIERS:
        raise Winn3ContractError("carrier-unsupported", ["carrier"])
    if carrier:
        normalized["carrier"] = resolved_carrier

    if resolved_carrier not in WINN3_CARRIER_PROFILE_CARRIERS:
        # Carrier-profile params are inert on direct-awg -- the client never
        # reads them into a profile (:1219-1245). Storing them anyway would be
        # an operator believing a profile is in force that is not, which is the
        # exact failure mode the spa_* refusal was written against. Refuse.
        #
        # `winn3` takes this branch for a DIFFERENT reason that lands in the
        # same place: a standalone session dials its own transport with its own
        # handshake and reads no MASQUE profile at all, so a profile param on a
        # winn3 node is exactly as inert as one on a direct-awg node, and
        # exactly as misleading to the operator who set it.
        #
        # The spa_* subset is deliberately EXCLUDED from this sweep and left to
        # the SPA block below, which is the order the client validates in
        # (carrier first, then SPA, ":1247-1249") and which produces the
        # accurate reason: an operator who put spa_mode=required on a direct-awg
        # node needs to be told the carrier cannot carry a knock, not that a
        # profile field is stray.
        stray = [
            k for k in WINN3_CARRIER_PROFILE_PARAMS
            if k not in WINN3_SPA_PARAMS and normalized.get(k, "")
        ]
        if stray:
            raise Winn3ContractError("carrier-profile-params-without-carrier", stray)
    else:
        missing = [
            k for k in WINN3_REQUIRED_CARRIER_PARAMS
            if not normalized.get(k, "")
        ]
        if missing:
            raise Winn3ContractError("carrier-profile-incomplete", missing)
        # _isSafeIniValue (:1473-1483), applied to every carrier param rather
        # than a chosen few: they all travel the same untrusted path.
        unsafe = []
        for key in WINN3_CARRIER_PROFILE_PARAMS:
            value = normalized.get(key, "")
            if not value:
                continue
            if len(value) > WINN3_MAX_INI_VALUE_LEN:
                unsafe.append(key)
                continue
            if any(ord(ch) < 0x20 or ord(ch) == 0x7F or ch in "[]" for ch in value):
                unsafe.append(key)
        if unsafe:
            raise Winn3ContractError("carrier-param-unsafe-for-ini", unsafe)

    # SPA (_spaRefusal, :1315-1421). Validated AFTER the carrier, because
    # whether SPA can be honoured at all depends on which carrier this is.
    mode = normalized.get("spa_mode", "").lower()
    if mode:
        normalized["spa_mode"] = mode
    other_spa = sorted(
        k for k in WINN3_SPA_PARAMS
        if k != "spa_mode" and normalized.get(k, "")
    )
    if not mode or mode == WINN3_SPA_MODE_OFF:
        if other_spa:
            # The engine's own rule (ErrSPAFieldWithoutMode): a target left
            # behind after SPA was turned off is an operator believing a
            # defence is armed that is not.
            raise Winn3ContractError("spa-params-without-mode", other_spa)
    else:
        if mode != WINN3_SPA_MODE_REQUIRED:
            raise Winn3ContractError("spa-mode-unsupported", ["spa_mode"])
        if resolved_carrier != WINN3_CARRIER_HTTP3:
            # knockdial.New refuses both other cases at CONSTRUCTION (:1352-1361).
            raise Winn3ContractError("spa-carrier-cannot-knock", ["spa_mode", "carrier"])
        if not winn3_is_ip_literal_endpoint(normalized.get("spa_target", "")):
            raise Winn3ContractError("spa-target-not-ip-literal", ["spa_target"])
        packet = _winn3_int_param(normalized, "spa_packet_size")
        if packet is not None and not (
            WINN3_SPA_MIN_PACKET_SIZE <= packet <= WINN3_SPA_MAX_PACKET_SIZE
        ):
            raise Winn3ContractError("spa-packet-size-out-of-range", ["spa_packet_size"])
        bucket = _winn3_int_param(normalized, "spa_bucket_window_seconds")
        skew = _winn3_int_param(normalized, "spa_max_skew_seconds")
        if bucket is not None and bucket < WINN3_SPA_MIN_BUCKET_WINDOW_SECONDS:
            raise Winn3ContractError("spa-timing-unusable", ["spa_bucket_window_seconds"])
        if skew is not None and skew < 0:
            raise Winn3ContractError("spa-timing-unusable", ["spa_max_skew_seconds"])
        if bucket is not None and skew is not None and skew < bucket:
            # A mismatch fails CLOSED and is completely silent: no knock ever
            # verifies and nothing reports an error anywhere (:1394-1398).
            raise Winn3ContractError(
                "spa-timing-unusable", ["spa_bucket_window_seconds", "spa_max_skew_seconds"]
            )

    # Drop keys that normalized to empty. An empty value is indistinguishable
    # from absent to the client, and omission cannot be misread
    # (lib/winn_carrier_profile_keys.dart:58-67).
    return {k: v for k, v in normalized.items() if v != ""}

def _node_field(node: Any, name: str) -> Any:
    """Read a column off a node row OR a dict, whichever the caller holds."""
    if hasattr(node, "keys") and name in node.keys():
        return node[name]
    if hasattr(node, "get"):
        return node.get(name)
    return None

def strict_stored_protocol_version(node: Any) -> str:
    raw = _node_field(node, "protocol_version")
    if not isinstance(raw, str):
        raise Winn3ContractError(
            "protocol-version-invalid",
            ["protocol_version"],
        )
    version = raw.strip().lower()
    if version not in (WINN_PROTOCOL_V1, WINN_PROTOCOL_V3):
        raise Winn3ContractError(
            "protocol-version-invalid",
            ["protocol_version"],
        )
    return version

def winn3_params_require_spa(params: dict) -> bool:
    return str(params.get("spa_mode", "") or "").strip().lower() == WINN3_SPA_MODE_REQUIRED

def parse_winn3_carrier_classes(value: Optional[Any]) -> list:
    """The migration plan stored on the node, as a list of class names.

    Stored comma-separated (the same shape the client emits as the INI
    `carrier_classes = udp,tcp,tls` line that the engine splits on). Blank or
    absent yields an empty list -- a standalone node with no plan is a
    registration error, NEVER a silently-udp-only default, for the reason
    documented on the client side: the engine substitutes an empty plan with
    {"udp"}, which forbids migration and disagrees with the gateway's floor
    (the empty-plan-handling divergence). This function never invents a plan.
    """
    if value is None:
        return []
    raw = str(value).strip()
    if not raw:
        return []
    out: list = []
    for piece in raw.split(","):
        name = piece.strip().lower()
        if name:
            out.append(name)
    return out

def winn3_effective_path_mtu(node: Any) -> int:
    """The OUTER path MTU this node plans at: its registration or the fleet
    default, exactly the resolution driver/carrier make for a missing path_mtu."""
    raw = _node_field(node, "path_mtu")
    if raw is None:
        return WINN3_DEFAULT_PATH_MTU
    try:
        value = int(raw)
    except (TypeError, ValueError):
        return WINN3_DEFAULT_PATH_MTU
    return value if value > 0 else WINN3_DEFAULT_PATH_MTU

def winn3_plan_floor_threshold(carrier_classes) -> int:
    """The outer path MTU where this plan stops being the never-promotes dead
    zone: 1280 + envelope(29) + the widest class's IPv6 overhead, which is the
    value driver.NewSizing compares against (winn3/driver/params.go:220-231,
    computed as the MAX of MinPathMTUForInnerIPv6 over the plan's classes and
    both address families -- IPv6 always binds, being 20 bytes wider)."""
    classes = list(carrier_classes or [])
    if not classes:
        return WINN3_IPV6_MINIMUM_LINK_MTU + WINN3_TUN_ENVELOPE_OVERHEAD
    widest = max(
        WINN3_PLAN_IPV6_CARRIER_OVERHEAD[c]
        for c in classes
        if c in WINN3_PLAN_IPV6_CARRIER_OVERHEAD
    )
    return (
        WINN3_IPV6_MINIMUM_LINK_MTU
        + WINN3_TUN_ENVELOPE_OVERHEAD
        + widest
    )

def winn3_standalone_plan_servable(path_mtu: int, carrier_classes: list) -> tuple:
    """Whether the CLIENT's engine will accept this standalone plan.

    Returns (servable, reason). The mirror of driver.NewSizing exactly: it
    refuses an empty plan, an unknown or duplicated class, and any plan whose
    path MTU lands in the 1280..threshold dead zone -- a session there
    resolves, bootstraps and CARRIES and can never promote, while the client
    would refuse the config outright. Saying yes here and having the client
    refuse is worse than saying no (winn/1 works); the client anti-downgrade
    rule means there is no partial state.
    """
    classes = list(carrier_classes or [])
    if not classes:
        return False, "path-mtu-plan-empty"
    if any(c not in WINN3_CARRIER_CLASSES for c in classes):
        return False, "path-mtu-plan-unknown-class"
    if len(set(classes)) != len(classes):
        return False, "path-mtu-plan-duplicate-class"
    if "udp" not in classes:
        # The current production datapath can size tcp/tls cover classes but
        # opens its actual carrier socket over UDP. Accepting a tcp/tls-only
        # plan would advertise a session every shipping client must refuse at
        # engine creation. Keep cover classes optional, but require the one
        # transport the deployed datapath can originate.
        return False, "path-mtu-plan-missing-udp"
    if path_mtu <= 0 or path_mtu > WINN3_MAX_MTU:
        return False, "path-mtu-out-of-range"
    if path_mtu < winn3_plan_floor_threshold(classes):
        return False, "path-mtu-dead-zone"
    return True, ""

def winn3_standalone_plan_for_node(node: Any) -> tuple:
    """The full standalone plan decision for one node.

    Returns (servable, reason, effective_path_mtu, classes). ONE function on
    the gate path AND the emission path so the two can never disagree about
    what a node is allowed to serve -- serving a plan the gate refused would be
    the "second piece of logic" the descriptor serving gate refuses to keep.
    """
    classes = parse_winn3_carrier_classes(_node_field(node, "carrier_classes"))
    path_mtu = winn3_effective_path_mtu(node)
    servable, reason = winn3_standalone_plan_servable(path_mtu, classes)
    return servable, reason, path_mtu, classes

def winn3_result_binding(node: Any) -> dict:
    data = dict(node)
    # Until H2 stores an identity digest the identity binds as "" (design
    # 3.17's pre-identity value), and a row with no valid stored descriptor
    # binds seq 0. The canary computes the same values, so a result still
    # binds to the slug's descriptor and generation, and a later identity,
    # descriptor or generation makes it stale.
    identity = data.get("winn3_identity_sha256") or ""
    generation = data.get("deployment_generation")
    if not isinstance(identity, str) or (identity and not re.fullmatch(r"[0-9a-f]{64}", identity)):
        raise ValueError("invalid identity binding")
    try:
        envelope = json.loads(data.get("winn3_descriptor_json") or "")
        seq = json.loads(base64.b64decode(envelope["payload"], validate=True))["seq"]
    except (ValueError, TypeError, KeyError):
        seq = 0
    if type(seq) is not int or seq <= 0:
        seq = 0
    if type(generation) is not int or generation < 0:
        raise ValueError("invalid deployment generation")
    return {"identity_sha256": identity, "seq": seq, "generation": generation}

WINN3_CANARY_NODES_FIELD_COUNT = 6

def winn3_canary_bindings() -> tuple:
    """({slug: {"static_public", "inner_v4"}}, {slugs bound more than once}).

    A slug named twice is returned as a conflict rather than resolved, so the
    registry build for that node refuses instead of guessing which probe
    identity is meant. An entry without six fields cannot be attributed to a
    node and is skipped (logged); that node then carries no canary and its
    canary fails closed exactly as an unconfigured one does.
    """
    bindings: dict = {}
    conflicts: set = set()

    def add(slug: str, public: str, inner: str, key_dir: str = "", endpoint: str = "", gateway_id: str = "") -> None:
        slug = str(slug or "").strip().lower()
        if not slug:
            return
        if slug in bindings:
            conflicts.add(slug)
            return
        bindings[slug] = {
            "static_public": str(public or "").strip(),
            "inner_v4": str(inner or "").strip(),
            "key_dir": key_dir, "gateway_endpoint": endpoint, "gateway_id": gateway_id,
        }

    legacy_slug = str(os.getenv("WINN3_CANARY_NODE_SLUG", "") or "").strip().lower()
    if legacy_slug:
        add(
            legacy_slug,
            os.getenv("WINN3_CANARY_STATIC_PUBLIC", ""),
            os.getenv("WINN3_CANARY_INNER_V4", ""),
            os.getenv("WINN3_CANARY_KEY_DIR", ""),
            os.getenv("WINN3_CANARY_GATEWAY_ENDPOINT", ""),
            os.getenv("WINN3_CANARY_GATEWAY_ID", ""),
        )
    for index, entry in enumerate(str(os.getenv("WINN3_CANARY_NODES", "") or "").split(), start=1):
        fields = entry.split("|")
        if len(fields) != WINN3_CANARY_NODES_FIELD_COUNT:
            logger.error("WINN3_CANARY_NODES entry %d is malformed; skipped", index)
            continue
        add(*fields)
    if not legacy_slug and not os.getenv("WINN3_CANARY_NODES", "").strip():
        with get_db() as conn:
            if conn.execute("SELECT 1 FROM sqlite_master WHERE name='winn3_canary_bindings'").fetchone():
                for row in conn.execute("SELECT * FROM winn3_canary_bindings ORDER BY slug"):
                    add(*(row[name] for name in ("slug", "static_public", "inner_v4", "key_dir", "gateway_endpoint", "gateway_id")))
    return bindings, conflicts

def _winn3_endpoint_host_port(value: Any) -> tuple:
    text = str(value or "").strip()
    if text.startswith("[") and "]:" in text:
        host, _, port = text.partition("]:")
        return host[1:], port
    host, sep, port = text.rpartition(":")
    return (host, port) if sep else (text, "")

def winn3_gateway_report_blockers(node: Any, descriptor: Optional[dict]) -> list:
    """Where the node's report of its gateway unit disagrees with what the hub serves.

    `descriptor` is the node's stored, validated descriptor ({} or None when it
    has none); descriptor comparisons are skipped without one, because
    winn3_descriptor_missing_or_invalid already names that.
    """
    blockers: list = []
    descriptor = descriptor or {}
    if descriptor:
        registered_host, _ = _winn3_endpoint_host_port(_node_field(node, "endpoint"))
        descriptor_host, _ = _winn3_endpoint_host_port(descriptor.get("endpoint"))
        try:
            registered_ip = ipaddress.ip_address(registered_host)
            descriptor_ip = ipaddress.ip_address(descriptor_host)
        except ValueError:
            registered_ip = descriptor_ip = None
        # A node whose public address changed re-registers its v1 endpoint on
        # the next heartbeat; its signed descriptor keeps the old address
        # until someone re-signs. Compared only when both are IP literals
        # (endpoint_not_ip_literal already names the other case).
        if registered_ip is not None and registered_ip != descriptor_ip:
            blockers.append("winn3_descriptor_endpoint_differs_from_registered_endpoint")
    report = parse_winn3_gateway_report(_node_field(node, "winn3_gateway_report_json"))
    if report is None:
        blockers.append("winn3_gateway_not_reported")
        return blockers
    if report["state"] == "absent":
        blockers.append("winn3_gateway_not_installed")
        return blockers
    if report["state"] != "active":
        blockers.append("winn3_gateway_not_running")
    if any(report[key] in (None, "") for key in (
        "forward", "resolver", "listen", "gateway_id", "inner_v4", "plan", "path_mtu",
    )):
        blockers.append("winn3_gateway_report_incomplete")
    if report["forward"] is False:
        # A reflector answers the handshake and forwards nothing: every client
        # connects and reaches nothing past the gateway.
        blockers.append("winn3_gateway_not_forwarding")
    if report["forward"] is True:
        # The gateway routes and NATs only -forward-cidr; a client the hub
        # addressed outside it has no route back (G: "THIS MUST BE THE SAME
        # SUBNET the control plane assigns client inner_v4 addresses from").
        # Compared with THIS node's pool (the /24 around its descriptor
        # router, fable_ruling_sync08_sync06 Q2), not with the envelope: the
        # two are the same /24 until per-node slices, and differ after.
        node_pool = winn3_node_inner_slice(node)
        try:
            forward_net = ipaddress.ip_network(report["forward_cidr"], strict=False)
        except ValueError:
            forward_net = None
        if forward_net is None:
            blockers.append("winn3_gateway_report_incomplete")
        elif node_pool is not None and forward_net != node_pool:
            blockers.append("winn3_gateway_forward_cidr_differs_from_node_pool")
    if report["resolver"] is False and descriptor.get("inner_resolver_v4"):
        # Every descriptor advertises inner_resolver_v4 (it must equal
        # inner_router_v4), so a gateway without -resolver hands clients a DNS
        # server nobody answers on.
        blockers.append("winn3_gateway_resolver_off")
    if descriptor:
        if report["gateway_id"]:
            try:
                descriptor_id = base64.b64decode(str(descriptor.get("gateway_id") or ""), validate=True)
            except Exception:
                descriptor_id = b""
            if descriptor_id != report["gateway_id"].encode("utf-8"):
                blockers.append("winn3_gateway_id_differs_from_descriptor")
        if report["inner_v4"] and report["inner_v4"] != str(descriptor.get("inner_router_v4") or "").strip():
            blockers.append("winn3_gateway_inner_v4_differs_from_descriptor")
        if report["listen"]:
            _, listen_port = _winn3_endpoint_host_port(report["listen"])
            _, descriptor_port = _winn3_endpoint_host_port(descriptor.get("endpoint"))
            if listen_port != descriptor_port:
                blockers.append("winn3_gateway_listen_port_differs_from_descriptor")
    if report["path_mtu"] is not None and report["path_mtu"] != winn3_effective_path_mtu(node):
        blockers.append("winn3_gateway_path_mtu_differs_from_hub")
    if report["plan"]:
        # Compared as sets: the hub and the gateway each keep their own
        # operator order, and only membership is checked here.
        hub_classes = set(parse_winn3_carrier_classes(_node_field(node, "carrier_classes")))
        if set(report["plan"].split(",")) != hub_classes:
            blockers.append("winn3_gateway_plan_differs_from_hub")
    return blockers

WINN3_DESCRIPTOR_DOMAIN = b"winsvpn-winn3-descriptor/v1"

WINN3_DESCRIPTOR_FORMAT_VERSION = 3

WINN3_DESCRIPTOR_KEY_SLOTS = ("g1", "g2", "g3")

WINN3_DESCRIPTOR_ALG_ED25519 = "ed25519"

WINN3_DESCRIPTOR_SUPPORTED_ALGS = (WINN3_DESCRIPTOR_ALG_ED25519,)

WINN3_ED25519_PUBLIC_KEY_BYTES = 32

WINN3_ED25519_SIGNATURE_BYTES = 64

WINN3_ED25519_SPKI_PREFIX = bytes.fromhex("302a300506032b6570032100")

WINN3_MIN_TAG_SIZE = 16

WINN3_MAX_TAG_SIZE = 32

WINN3_MIN_ADMISSION_SECRET_BYTES = 32

WINN3_STATIC_PUBLIC_KEY_BYTES = 32

WINN3_DUAL_AUTH_ED25519_PUBLIC_KEY_BYTES = 32

WINN3_DUAL_AUTH_MLDSA65_PUBLIC_KEY_BYTES = 1952

WINN3_MIN_GATEWAY_ID_BYTES = 1

WINN3_MAX_GATEWAY_ID_BYTES = 255

WINN3_MIN_BUCKET_WINDOW_SECONDS_CORE = 1

WINN3_MAX_BUCKET_CANDIDATES = 4096

WINN3_PADDING_POLICIES = ("none", "bucket", "mimic")

WINN3_MAX_LIVE_ADMISSION_KEYS = 2

WINN3_MAX_ADMISSION_HMAC_BUDGET = 64

WINN3_MIN_DESCRIPTOR_TTL_SECONDS = 3600

WINN3_MAX_DESCRIPTOR_TTL_SECONDS = 30 * 24 * 3600

WINN3_DESCRIPTOR_REQUIRED_FIELDS = (
    "admission_gen", "admission_secret", "alg", "bucket_window_s", "endpoint",
    "gateway_id", "iat", "inner_resolver_v4", "inner_router_v4", "kid",
    "max_skew_s", "node", "not_after", "padding", "seq", "static_pub",
    "tag_size", "v",
)

WINN3_DESCRIPTOR_OPTIONAL_FIELDS = ("auth_ed25519", "auth_mldsa65")

WINN3_DESCRIPTOR_PLAIN_IPV4_FIELDS = ("inner_resolver_v4", "inner_router_v4")

WINN3_DESCRIPTOR_CLIENT_CAPABILITY = "supports_winn3_descriptor"

WINN3_DUALAUTH_CLIENT_CAPABILITY = "supports_winn3_dualauth"

def winn3_client_advertises_dualauth(capabilities: Optional[dict]) -> bool:
    """True only when the client sent supports_winn3_dualauth as JSON true.

    Missing is False. A non-bool value is malformed and refused.
    """
    if not capabilities:
        return False
    if WINN3_DUALAUTH_CLIENT_CAPABILITY not in capabilities:
        return False
    return winn3_capability_bool(
        capabilities.get(WINN3_DUALAUTH_CLIENT_CAPABILITY),
        WINN3_DUALAUTH_CLIENT_CAPABILITY,
    )

def winn3_descriptor_has_dual_auth(descriptor: Optional[dict]) -> bool:
    if not descriptor:
        return False
    ed = descriptor.get("auth_ed25519")
    ml = descriptor.get("auth_mldsa65")
    return bool(isinstance(ed, str) and ed.strip()) and bool(
        isinstance(ml, str) and ml.strip()
    )

def winn3_dual_auth_keys_for_capabilities(
    descriptor: Optional[dict],
    capabilities: Optional[dict],
) -> dict:
    """The dual-auth public keys THIS client is served.

    Both keys, or neither. The pair is included only when the client
    explicitly advertised supports_winn3_dualauth=true AND the descriptor
    carries both keys. A true advertisement against a dual-provisioned
    descriptor that would drop either key is a silent authentication
    downgrade and is refused. A legacy descriptor with neither key is
    preserved for dual-auth-capable clients and everyone else.
    """
    advertised = winn3_client_advertises_dualauth(capabilities)
    raw = descriptor or {}
    ed = raw.get("auth_ed25519")
    ml = raw.get("auth_mldsa65")
    has_ed = isinstance(ed, str) and bool(ed.strip())
    has_ml = isinstance(ml, str) and bool(ml.strip())
    if advertised:
        if has_ed and has_ml:
            return {
                "auth_ed25519": str(ed).strip(),
                "auth_mldsa65": str(ml).strip(),
            }
        if has_ed or has_ml:
            raise Winn3ContractError(
                "descriptor-dual-auth-half-provisioned",
                ["auth_ed25519", "auth_mldsa65"],
            )
        return {}
    return {}

def winn3_freshness_geometry(bucket_window_s: int, max_skew_s: int) -> tuple:
    """(spread, candidates, acceptance_span_seconds), mirroring core exactly.

    core Freshness.resolve() (params.go:253-273):
        spread     = ceil(skew / window)      -- integer ceiling
        candidates = 2*spread + 1
    and NewResponder (handshake.go:494-506) sets the handshake replay cache
    lifetime to exactly (2*spread+1)*window.

    THE TWO ARE THE SAME NUMBER ON PURPOSE. The cache must remember a captured
    initiation for as long as that initiation could still verify; if the two
    ever drift apart, the gap is a span in which a censor's recorded packet is
    a working gateway detector again -- the exact hole the acceptance-window
    test in the gateway-table lane pins. Every rotation deadline this hub
    computes is expressed in terms of this one function so that a change to the
    freshness parameters moves both at once and cannot separate them.
    """
    window = int(bucket_window_s)
    skew = int(max_skew_s)
    if window < WINN3_MIN_BUCKET_WINDOW_SECONDS_CORE:
        raise Winn3ContractError("bucket-window-below-one-second", ["bucket_window_s"])
    if skew < window:
        raise Winn3ContractError("max-skew-below-bucket-window", ["max_skew_s"])
    spread = -(-skew // window)
    candidates = 2 * spread + 1
    if candidates > WINN3_MAX_BUCKET_CANDIDATES:
        raise Winn3ContractError("bucket-candidates-over-core-ceiling", ["max_skew_s"])
    return spread, candidates, candidates * window

def winn3_admission_hmac_cost(candidates: int, live_keys: int) -> int:
    """HMACs an unauthenticated datagram costs the gateway before it is dropped.

    keys outermost, buckets innermost, no early exit on a failure -- so it is
    exactly the product. See the budget note above.
    """
    return int(candidates) * int(live_keys)

def winn3_descriptor_public_keys() -> dict:
    """slot -> raw 32-byte Ed25519 public key, from the environment.

    Base64 of the RAW key, which is what `openssl pkey -pubout -outform DER |
    tail -c 32 | base64` produces and what the client's --dart-define carries.
    A slot that is set but unusable is DROPPED rather than tolerated: a typo
    must degrade to "that key does not exist", never to a verifier that accepts
    something it should not.
    """
    keys: dict = {}
    for slot in WINN3_DESCRIPTOR_KEY_SLOTS:
        encoded = (os.getenv(f"WINN3_DESCRIPTOR_PUBKEY_{slot.upper()}") or "").strip()
        if not encoded:
            continue
        try:
            raw = base64.b64decode(encoded, validate=True)
        except Exception:
            continue
        if len(raw) == WINN3_ED25519_PUBLIC_KEY_BYTES:
            keys[slot] = raw
    return keys

WINN3_DESCRIPTOR_SIGNATURE_CACHE_LIMIT = 256

_WINN3_DESCRIPTOR_SIGNATURE_CACHE = OrderedDict()

_WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING = None

_WINN3_DESCRIPTOR_SIGNATURE_CACHE_LOCK = threading.Lock()

def winn3_verify_descriptor_signature(payload: bytes, signature: bytes, kid: str) -> str:
    """Verify DOMAIN || 0x00 || payload under the slot named by `kid`.

    openssl(1) rather than a Python library for the reason already recorded at
    the announcement block (ANNOUNCE_SIGNATURE_DOMAIN): control-plane-requirements.lock is hash-pinned
    and `cryptography` is not in it. Ed25519 verification is one-shot, so
    openssl needs seekable files for both the message and the signature.

    Returns the accepting slot id. Raises Winn3ContractError otherwise, with a
    reason and NEVER any bytes.

    P-15 caches successful signature checks only. Shape, node binding and
    clock checks remain in winn3_stored_descriptor on every consumption.
    """
    global _WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING
    slot = (kid or "").strip().lower()
    if slot not in WINN3_DESCRIPTOR_KEY_SLOTS:
        raise Winn3ContractError("descriptor-unknown-key-slot", ["kid"])
    if len(signature) != WINN3_ED25519_SIGNATURE_BYTES:
        raise Winn3ContractError("descriptor-signature-length", ["sig"])
    ring = winn3_descriptor_public_keys()
    ring_digest = hashlib.sha256(json.dumps(
        {name: key.hex() for name, key in ring.items()},
        sort_keys=True, separators=(",", ":"),
    ).encode("ascii")).digest()
    # Length framing makes the tuple unambiguous. Retain only the digest and
    # accepting slot, never payload or signature bytes in the cache.
    digest = hashlib.sha256()
    for field in (slot.encode("ascii"), payload, signature, ring_digest):
        digest.update(len(field).to_bytes(8, "big"))
        digest.update(field)
    cache_key = digest.digest()
    with _WINN3_DESCRIPTOR_SIGNATURE_CACHE_LOCK:
        if _WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING != ring_digest:
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE.clear()
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING = ring_digest
        accepted_slot = _WINN3_DESCRIPTOR_SIGNATURE_CACHE.get(cache_key)
        if accepted_slot is not None:
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE.move_to_end(cache_key)
            return accepted_slot
    if not ring:
        raise Winn3ContractError("descriptor-no-verification-keys-configured", ["kid"])
    raw = ring.get(slot)
    if raw is None:
        raise Winn3ContractError("descriptor-key-slot-not-provisioned", ["kid"])
    message = WINN3_DESCRIPTOR_DOMAIN + b"\x00" + payload
    with tempfile.TemporaryDirectory() as work_dir:
        key_path = os.path.join(work_dir, "descriptor.der")
        msg_path = os.path.join(work_dir, "descriptor.bin")
        sig_path = os.path.join(work_dir, "descriptor.sig")
        with open(key_path, "wb") as handle:
            handle.write(WINN3_ED25519_SPKI_PREFIX + raw)
        with open(msg_path, "wb") as handle:
            handle.write(message)
        with open(sig_path, "wb") as handle:
            handle.write(signature)
        completed = subprocess.run(
            [
                "openssl", "pkeyutl", "-verify", "-rawin", "-pubin",
                "-inkey", key_path, "-keyform", "DER",
                "-sigfile", sig_path, "-in", msg_path,
            ],
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15,
        )
    if completed.returncode != 0:
        raise Winn3ContractError("descriptor-signature-invalid", ["sig"])
    with _WINN3_DESCRIPTOR_SIGNATURE_CACHE_LOCK:
        # A concurrent verifier may have observed a ring change while openssl
        # ran. Its cleared cache must not regain entries from the old ring.
        if _WINN3_DESCRIPTOR_SIGNATURE_CACHE_RING == ring_digest:
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE[cache_key] = slot
            _WINN3_DESCRIPTOR_SIGNATURE_CACHE.move_to_end(cache_key)
            while len(_WINN3_DESCRIPTOR_SIGNATURE_CACHE) > WINN3_DESCRIPTOR_SIGNATURE_CACHE_LIMIT:
                _WINN3_DESCRIPTOR_SIGNATURE_CACHE.popitem(last=False)
    return slot

def _winn3_descriptor_b64_field(payload: dict, key: str, *, exact_len: int = 0,
                                min_len: int = 0, max_len: int = 0) -> bytes:
    value = payload.get(key)
    if not isinstance(value, str) or not value.strip():
        raise Winn3ContractError("descriptor-field-not-base64", [key])
    try:
        raw = base64.b64decode(value.strip(), validate=True)
    except Exception:
        raise Winn3ContractError("descriptor-field-not-base64", [key]) from None
    if exact_len and len(raw) != exact_len:
        raise Winn3ContractError("descriptor-field-wrong-length", [key])
    if min_len and len(raw) < min_len:
        raise Winn3ContractError("descriptor-field-too-short", [key])
    if max_len and len(raw) > max_len:
        raise Winn3ContractError("descriptor-field-too-long", [key])
    return raw

def _winn3_descriptor_int_field(payload: dict, key: str) -> int:
    value = payload.get(key)
    if isinstance(value, bool) or not isinstance(value, int):
        raise Winn3ContractError("descriptor-field-not-an-integer", [key])
    return value

def validate_winn3_descriptor_payload(payload: Any, *, slug: str) -> dict:
    """Every rule a descriptor must satisfy, checked before it is ever stored.

    The hub validates for the same reason it validates protocol_params: a bad
    value here is not a warning, it is every winn/3 client of that node unable
    to complete a handshake, silently, because the gateway drops a failed
    admission tag without answering (design section 4.3). A 400 to one operator
    is the cheap version of that.

    Returns a normalized dict. Never returns, logs or raises with any secret
    value -- see WINN3_DESCRIPTOR_SECRET_FIELDS.
    """
    if not isinstance(payload, dict):
        raise Winn3ContractError("descriptor-not-an-object")
    present = {str(k).strip() for k in payload.keys()}
    missing = sorted(set(WINN3_DESCRIPTOR_REQUIRED_FIELDS) - present)
    if missing:
        raise Winn3ContractError("descriptor-missing-fields", missing)
    unknown = sorted(
        present - set(WINN3_DESCRIPTOR_REQUIRED_FIELDS) - set(WINN3_DESCRIPTOR_OPTIONAL_FIELDS)
    )
    if unknown:
        raise Winn3ContractError("descriptor-unknown-fields", unknown)

    if _winn3_descriptor_int_field(payload, "v") != WINN3_DESCRIPTOR_FORMAT_VERSION:
        raise Winn3ContractError("descriptor-unsupported-format-version", ["v"])
    alg = str(payload.get("alg") or "").strip().lower()
    if alg not in WINN3_DESCRIPTOR_SUPPORTED_ALGS:
        raise Winn3ContractError("descriptor-unsupported-algorithm", ["alg"])
    kid = str(payload.get("kid") or "").strip().lower()
    if kid not in WINN3_DESCRIPTOR_KEY_SLOTS:
        raise Winn3ContractError("descriptor-unknown-key-slot", ["kid"])

    node_slug = str(payload.get("node") or "").strip().lower()
    if not node_slug:
        raise Winn3ContractError("descriptor-missing-node", ["node"])
    if node_slug != (slug or "").strip().lower():
        # A descriptor names the node it describes, INSIDE the signed bytes.
        # Without this, a signed descriptor for gateway A could be installed on
        # gateway B and every client of B would seal initiations that only A
        # can open -- and would do so silently, since the gateway never answers
        # a failed tag. It is the control-plane half of the GatewayID binding
        # core already does on the wire (params.go:284-288).
        raise Winn3ContractError("descriptor-node-mismatch", ["node"])

    endpoint = str(payload.get("endpoint") or "").strip()
    if not winn3_is_ip_literal_endpoint(endpoint):
        raise Winn3ContractError("descriptor-endpoint-not-ip-literal", ["endpoint"])

    plain_ipv4: dict = {}
    for field in WINN3_DESCRIPTOR_PLAIN_IPV4_FIELDS:
        text = str(payload.get(field) or "").strip()
        if not winn3_is_inner_ipv4(text):
            raise Winn3ContractError("descriptor-inner-address-not-ipv4", [field])
        plain_ipv4[field] = text
    if plain_ipv4["inner_resolver_v4"] != plain_ipv4["inner_router_v4"]:
        raise Winn3ContractError(
            "descriptor-resolver-does-not-match-gateway-bind",
            ["inner_resolver_v4", "inner_router_v4"],
        )

    _winn3_descriptor_b64_field(
        payload, "static_pub", exact_len=WINN3_STATIC_PUBLIC_KEY_BYTES)
    gateway_id_raw = _winn3_descriptor_b64_field(
        payload, "gateway_id",
        min_len=WINN3_MIN_GATEWAY_ID_BYTES, max_len=WINN3_MAX_GATEWAY_ID_BYTES)
    if winn3_operator_text_has_edge_whitespace(gateway_id_raw):
        # Trap 3. See winn3_operator_text_has_edge_whitespace: one trailing
        # space here keys 9 bytes on the gateway and on Apple and 8 on Android,
        # and neither end can ever discover the disagreement because the value
        # is never transmitted. Refused at upload, where it costs one operator
        # one 400, rather than shipped to a fleet.
        raise Winn3ContractError(
            "descriptor-gateway-id-has-edge-whitespace", ["gateway_id"])
    admission_raw = _winn3_descriptor_b64_field(
        payload, "admission_secret", min_len=WINN3_MIN_ADMISSION_SECRET_BYTES)
    if winn3_operator_text_has_edge_whitespace(admission_raw):
        # The same asymmetry applies to the admission secret -- Android trims
        # it, the gateway does not -- with the same silent outcome. The key
        # file's trailing newline is stripped by every consumer by rule; any
        # OTHER edge whitespace is an accident, and an accident here is a
        # session that builds and then never answers.
        raise Winn3ContractError(
            "descriptor-admission-secret-has-edge-whitespace",
            ["admission_secret"])
    # TRAP 2, made checkable. The admission secret is OPAQUE BYTES: keygen
    # writes 64 ASCII hex characters and every consumer keys with the file's
    # bytes after trimming a trailing CR/LF and nothing else. base64 of the 32
    # DECODED bytes is 32 bytes here and is the exact defect the conformance
    # suite pins as `admission-secret-is-opaque-bytes`: the gateway admits the
    # datagram, BUILDS a session, and then goes completely silent.
    #
    # This hub, installer, gateway, signer and provisioner are one shipping
    # toolchain. Its canonical secret is exactly the 64 lowercase ASCII hex
    # bytes keygen writes, used opaquely without hex decoding. Accepting any
    # other shape here publishes a descriptor the installed gateway refuses,
    # so reject it while the operator can still correct one upload.
    if len(admission_raw) != 64 or not re.fullmatch(
        rb"[0-9a-f]{64}", admission_raw
    ):
        raise Winn3ContractError(
            "descriptor-admission-secret-noncanonical", ["admission_secret"]
        )

    tag_size = _winn3_descriptor_int_field(payload, "tag_size")
    if not (WINN3_MIN_TAG_SIZE <= tag_size <= WINN3_MAX_TAG_SIZE):
        raise Winn3ContractError("descriptor-tag-size-out-of-range", ["tag_size"])

    padding = str(payload.get("padding") or "").strip().lower()
    if padding not in WINN3_PADDING_POLICIES:
        raise Winn3ContractError("descriptor-unknown-padding-policy", ["padding"])

    window = _winn3_descriptor_int_field(payload, "bucket_window_s")
    skew = _winn3_descriptor_int_field(payload, "max_skew_s")
    spread, candidates, span = winn3_freshness_geometry(window, skew)
    # The rotation budget, checked at the WORST case rather than the current
    # one: a descriptor is accepted only if it would still be affordable while
    # a rotation is in flight, because otherwise the refusal would land on the
    # operator mid-rotation, which is the worst possible moment for it.
    if winn3_admission_hmac_cost(
        candidates, WINN3_MAX_LIVE_ADMISSION_KEYS
    ) > WINN3_MAX_ADMISSION_HMAC_BUDGET:
        raise Winn3ContractError(
            "descriptor-freshness-exceeds-rotation-budget",
            ["bucket_window_s", "max_skew_s"],
        )

    gen = _winn3_descriptor_int_field(payload, "admission_gen")
    if gen < 0:
        raise Winn3ContractError("descriptor-negative-admission-generation", ["admission_gen"])
    seq = _winn3_descriptor_int_field(payload, "seq")
    if seq < 0:
        raise Winn3ContractError("descriptor-negative-sequence", ["seq"])
    iat = _winn3_descriptor_int_field(payload, "iat")
    not_after = _winn3_descriptor_int_field(payload, "not_after")
    ttl = not_after - iat
    if ttl < WINN3_MIN_DESCRIPTOR_TTL_SECONDS:
        raise Winn3ContractError("descriptor-ttl-too-short", ["not_after"])
    if ttl > WINN3_MAX_DESCRIPTOR_TTL_SECONDS:
        # An unbounded ttl is an unbounded retirement deadline: the hub could
        # never say when an old admission key stops being reachable from a
        # cached config.
        raise Winn3ContractError("descriptor-ttl-too-long", ["not_after"])

    # Wall-clock lifetime. The store path checks shape; the clock is checked
    # here so the SERVE path (which re-runs this validator on every read)
    # refuses expired or not-yet-valid descriptors, not just the store path.
    now = int(time.time())
    if now < iat:
        raise Winn3ContractError("descriptor-not-yet-valid", ["iat"])
    if now >= not_after:
        raise Winn3ContractError("descriptor-expired", ["not_after"])

    # Dual-signature attestation keys are OPTIONAL as a pair: absent on
    # legacy nodes; both present, exactly sized, on dual-provisioned nodes. A
    # half-provisioned descriptor is refused.
    if payload.get("auth_ed25519") is not None or payload.get("auth_mldsa65") is not None:
        _winn3_descriptor_b64_field(
            payload, "auth_ed25519",
            exact_len=WINN3_DUAL_AUTH_ED25519_PUBLIC_KEY_BYTES)
        _winn3_descriptor_b64_field(
            payload, "auth_mldsa65",
            exact_len=WINN3_DUAL_AUTH_MLDSA65_PUBLIC_KEY_BYTES)

    descriptor = {
        "v": WINN3_DESCRIPTOR_FORMAT_VERSION,
        "alg": alg,
        "kid": kid,
        "node": node_slug,
        "endpoint": endpoint,
        # Plain dotted-quad text, NOT base64 -- see
        # WINN3_DESCRIPTOR_PLAIN_IPV4_FIELDS. Each reaches its `[winn]` key
        # exactly as it is written here, with no decode anywhere to disagree
        # about.
        **plain_ipv4,
        "static_pub": str(payload["static_pub"]).strip(),
        "gateway_id": str(payload["gateway_id"]).strip(),
        "admission_secret": str(payload["admission_secret"]).strip(),
        "admission_gen": gen,
        "tag_size": tag_size,
        "padding": padding,
        "bucket_window_s": window,
        "max_skew_s": skew,
        "seq": seq,
        "iat": iat,
        "not_after": not_after,
        # Derived, not signed -- recomputed anywhere it is needed so the two
        # can never disagree.
        "_spread": spread,
        "_bucket_candidates": candidates,
        "_acceptance_span_s": span,
        "_ttl_s": ttl,
    }
    # The attestation keys ride the descriptor to the client, so a dual-auth
    # node's client learns the exact keys the gateway will accept. Included
    # only after the pair validated above; a legacy descriptor has neither.
    if payload.get("auth_ed25519") is not None:
        descriptor["auth_ed25519"] = str(payload["auth_ed25519"]).strip()
        descriptor["auth_mldsa65"] = str(payload["auth_mldsa65"]).strip()
    return descriptor

def parse_winn3_descriptor_envelope(value: Optional[str]) -> dict:
    """Read a stored descriptor envelope. Mirrors parse_protocol_params: a
    blank or malformed slot is an EMPTY dict, never an exception, because this
    is on the request path and a stored-blob problem must degrade to "no
    descriptor", not to a 500 for a paying user.
    """
    if not value:
        return {}
    try:
        data = json.loads(value)
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    payload = str(data.get("payload") or "")
    signature = str(data.get("sig") or "")
    if not payload or not signature:
        return {}
    return {"payload": payload, "sig": signature}

def winn3_stored_descriptor(node: Any, *, reason_sink: Optional[dict] = None,
                            clock_tolerant: bool = False) -> dict:
    """The validated payload of whatever descriptor is stored on a node row.

    Returns {} when there is none or it no longer validates. Re-validated on
    the READ path for the same reason protocol_params is: a row can predate the
    validator, and serving a descriptor the gateway will not honour is worse
    than serving none.

    `reason_sink`, when given, is a dict that receives {"reason": ...} from
    the Winn3ContractError that refused the blob. Serve-path callers use it so
    a forged signature, an expired descriptor and an unclassifiable blob do
    not all read as one generic refusal.

    `clock_tolerant=True` tolerates ONLY the two clock refusals
    (descriptor-expired, descriptor-not-yet-valid) and exists for ONE serving
    caller: the inner-address allocator. (winn3_descriptor_expiry also uses it,
    read-only, to report an expired descriptor's not_after; it decides nothing.)
    A gateway keeps answering on its
    inner_router_v4 after the hub's descriptor clock lapses -- expiry is a
    SERVING control, not a gateway stop -- so an authentic expired
    descriptor's address claim must still be reserved (F-02, final audit
    2026-08-28) or the hub can hand a device the address of a live gateway.
    Every other check (shape, node binding, and above all the SIGNATURE)
    applies in full; only the clock is forgiven. It must NEVER be used on a
    serve path: the payload it returns failed the clock check.
    """
    try:
        raw = (
            node["winn3_descriptor_json"]
            if hasattr(node, "keys") and "winn3_descriptor_json" in node.keys()
            else (node.get("winn3_descriptor_json") if hasattr(node, "get") else None)
        )
    except Exception:
        raw = None
    envelope = parse_winn3_descriptor_envelope(raw)
    if not envelope:
        return {}
    slug = ""
    try:
        slug = str(node["slug"] if hasattr(node, "keys") else node.get("slug") or "")
    except Exception:
        slug = ""
    try:
        payload_bytes = base64.b64decode(envelope["payload"], validate=True)
        signature_bytes = base64.b64decode(envelope["sig"], validate=True)
        decoded = json.loads(payload_bytes.decode("utf-8"))
        try:
            normalized = validate_winn3_descriptor_payload(decoded, slug=slug)
        except Winn3ContractError as clock_exc:
            # F-02: forgive ONLY the clock. Every check that ran before the
            # clock in validate_winn3_descriptor_payload (shape, field set,
            # alg, kid slot, node binding, sizes, ttl bounds) has passed by
            # construction; the signature is still verified below. The value
            # returned is the raw decoded payload, whose field set the
            # missing/unknown checks already pinned to the closed schema.
            if not (clock_tolerant and clock_exc.reason in (
                    "descriptor-expired", "descriptor-not-yet-valid")):
                raise
            normalized = decoded
        kid = str(normalized.get("kid") or "").strip().lower()
        # Serve path re-verification (P0-1): the cryptographic control must be
        # enforced where the descriptor is consumed, not only where it is
        # stored. A forged or tampered row (e.g. a GCS-replica restore) fails
        # here and is served to no client -- and, with clock_tolerant, is
        # trusted by no allocator either.
        winn3_verify_descriptor_signature(payload_bytes, signature_bytes, kid)
        return normalized
    except Winn3ContractError as exc:
        if reason_sink is not None:
            reason_sink["reason"] = exc.reason
        return {}
    except Exception:
        return {}

def resolve_served_winn3_descriptor(
    node: Any,
    *,
    capabilities: dict,
    served_protocol_version: str,
) -> tuple:
    """Decide whether THIS request is served a descriptor. Returns (envelope, reason).

    THE DESCRIPTOR RIDES THE winn/3 GATE AND ADDS ONE FLAG. It is never served
    unless resolve_served_winn_protocol already decided this request gets
    winn/3, which means every refusal that gate makes is inherited here for
    free and cannot be bypassed:

      * stealth_active + winn/3 is a client-side refusal, and stealth_active is
        a PER-REQUEST choice, so the same node is winn/3-servable to one
        request and not the next. Because the descriptor is downstream of the
        gate, a stealth request against a registered winn/3 node is refused
        (not rewritten to winn/1) and no descriptor is served, with no second
        piece of logic that could disagree with the first. An explicit winn/1
        node still gets winn/1 and no descriptor.
      * Double VPN, an unusable obfuscation profile, an out-of-range MTU, a
        non-literal endpoint, an invalid params blob -- all already refused
        upstream.

    The added flag is supports_winn3_descriptor, DEFAULT FALSE. A client that
    speaks AWG-carried winn/3 but knows nothing about standalone descriptors
    must not be handed one; it would at best ignore it and at worst refuse.

    Dual-auth public keys are a second, stricter gate on the same envelope.
    The signed payload is stored and returned verbatim (the client verifies
    those exact bytes). The pair is RELEASED onto the served envelope only
    when the client sent supports_winn3_dualauth as an explicit true. A
    dual-auth-required request (true, against a dual-provisioned descriptor)
    that would drop either key is refused rather than silently downgraded.
    A legacy descriptor with neither key is preserved. Malformed capability
    values are refused, never coerced.
    """
    advertised = winn3_client_advertises_dualauth(capabilities)
    if served_protocol_version != WINN_PROTOCOL_V3:
        return {}, "not-serving-winn3"
    if not bool((capabilities or {}).get(WINN3_DESCRIPTOR_CLIENT_CAPABILITY)):
        return {}, "client-not-descriptor-capable"
    try:
        raw = (
            node["winn3_descriptor_json"]
            if hasattr(node, "keys") and "winn3_descriptor_json" in node.keys()
            else (node.get("winn3_descriptor_json") if hasattr(node, "get") else None)
        )
    except Exception:
        raw = None
    envelope = parse_winn3_descriptor_envelope(raw)
    if not envelope:
        return {}, "no-descriptor-registered"
    refusal: dict = {}
    stored = winn3_stored_descriptor(node, reason_sink=refusal)
    if not stored:
        # The specific Winn3ContractError reason when there is one (a forged
        # signature, an expired descriptor, a field the client would refuse),
        # the generic class when the blob failed outside the contract (unreadable
        # bytes): a GCS-replica restore that is not even a descriptor names no
        # contract reason.
        return {}, refusal.get("reason") or "descriptor-does-not-validate"
    keys = winn3_dual_auth_keys_for_capabilities(stored, capabilities)
    if advertised and winn3_descriptor_has_dual_auth(stored):
        if (
            keys.get("auth_ed25519") != stored.get("auth_ed25519")
            or keys.get("auth_mldsa65") != stored.get("auth_mldsa65")
        ):
            raise Winn3ContractError(
                "client-dual-auth-downgrade",
                ["auth_ed25519", "auth_mldsa65"],
            )
    served = dict(envelope)
    served.update(keys)
    return served, "winn3-descriptor"

WINN3_INNER_POOL_CIDR = (os.getenv("WINN3_INNER_POOL_CIDR") or "10.10.0.0/24").strip()

WINN3_INNER_POOL_PREFIXLEN = 24

def _winn3_inner_pool_or_reason() -> tuple:
    """(network, None) for a usable pool, or (None, the exact reason).

    THE ONE IMPLEMENTATION OF THE POOL RULE (D15, 2026-08-12). Everything that
    needs to know whether the pool is usable -- the runtime validator
    winn3_inner_pool() and the startup guard require_winn3_inner_pool() --
    comes through here, so the two cannot reach different verdicts.

    They previously could, and did. D7 pinned the pool to /24 but left a second
    copy of the rule inline in startup_event(), and the two disagreed three
    ways: a malformed CIDR returned None silently here and was swallowed by
    `except ValueError: pass` there; a non-IPv4 pool was silent in both; only a
    too-wide pool was ever reported. So `10.10.0/24` -- one missing octet --
    started the hub cleanly, returned "" from every allocation, failed every
    in-pool check (misreporting healthy descriptors as "outside pool" in the
    readiness path), and downgraded the entire fleet to winn/1 with no
    diagnostic anywhere. Zero-working dressed as running, which is strictly
    worse than the half-working state D7 already refuses to serve. Divergence
    between a guard and its validator is how that happened, so the fix is that
    the guard no longer has an opinion of its own to diverge with.

    THE WIDTH IS EXACTLY /24, in both directions:

      WIDER breaks client derivation. The mobile hosts derive inner
      reachability against a hard /24 floor -- Android
      WinnV3Resolvers.sameInnerBlock (0xFFFFFF00) in WinnV3Posture.kt, Apple
      WinsWinn3Resolvers.sameInnerBlock (0xFFFF_FF00) in
      WinsWinn3SessionStart.swift -- so a /16 silently splits the fleet at
      device 254: the first ~253 clients in 10.10.0.0/24 can derive 10.10.0.1
      while any client allocated in 10.10.1.x cannot. Windows/Linux do not
      check it at all (winn3_posture.h takes `dns_servers_are_inner` as a host
      DECLARATION), so there it fails even quieter.

      NARROWER has no articulated use and includes the degenerate case: a /32
      offers one address for the entire fleet -- the gateway's own inner
      address and nothing else -- so every device after the first gets "".

    A future /25 sharding scheme is a deliberate revisit that owes a
    client-derivation analysis, not latitude left open by an inequality.

    Returns the reason as a sentence fragment that reads correctly after
    "WINN3_INNER_POOL_CIDR=<value> ", so the log line and the startup refusal
    say the same words.
    """
    try:
        network = ipaddress.ip_network(WINN3_INNER_POOL_CIDR, strict=False)
    except ValueError as exc:
        return None, (
            "is not a valid CIDR ({}). Give a dotted-quad network and a "
            "prefix, e.g. 10.10.0.0/24. An abbreviated form such as "
            "'10.10.0/24' is NOT accepted -- that typo used to start the hub "
            "silently and downgrade every device to winn/1.".format(exc)
        )
    if not isinstance(network, ipaddress.IPv4Network):
        return None, (
            "is IPv6, and winn/3 inner addressing is IPv4-only: the "
            "descriptor's inner_router_v4 and inner_resolver_v4 are dotted "
            "quads and the gateway's -forward carries IPv4 only. Give an "
            "IPv4 /24, e.g. 10.10.0.0/24."
        )
    if network.prefixlen != WINN3_INNER_POOL_PREFIXLEN:
        return None, (
            "is a /{}, and the pool is pinned to EXACTLY /24. A wider pool "
            "(e.g. /16) allocates clients outside the derivable /24 and "
            "silently breaks their sessions at device 254, because the mobile "
            "clients derive inner reachability against a hard /24 floor "
            "(Android WinnV3Resolvers.sameInnerBlock 0xFFFFFF00 in "
            "WinnV3Posture.kt, Apple WinsWinn3Resolvers.sameInnerBlock in "
            "WinsWinn3SessionStart.swift), and Windows/Linux winn3_posture.h "
            "does not check it at all (dns_servers_are_inner is a host "
            "declaration) so there the same pool declares a resolver inner "
            "that the tun layer drops. A narrower pool has no supported use "
            "and a /32 allocates nothing at all. Pin the pool to /24 (e.g. "
            "10.10.0.0/24) and set WINN3_GATEWAY_INNER_V4 / descriptor "
            "inner_router_v4 to an address inside it.".format(network.prefixlen)
        )
    return network, None

def winn3_inner_pool() -> Optional[Any]:
    """The configured inner pool, or None -- reason logged -- when unusable.

    THE single validator. Every None is accompanied by an error line naming the
    value and the exact reason: malformed, IPv6, or the wrong width. A pool
    refused without a reason is the silent fleet-wide downgrade D15 removes.

    None degrades to "standalone v3 unavailable" everywhere it is consulted --
    never to an allocation from a guessed range. Since require_winn3_inner_pool()
    now refuses to start on exactly these inputs, the None path is unreachable
    in production and is kept as defence in depth: a 503 from an allocation
    would take down an ORDINARY winn/1 login, and v1 is the product while v3 is
    the addition.
    """
    network, reason = _winn3_inner_pool_or_reason()
    if network is None:
        logger.error("WINN3_INNER_POOL_CIDR=%s %s", WINN3_INNER_POOL_CIDR, reason)
        return None
    return network

def winn3_node_inner_slice(node: Any) -> Optional[Any]:
    """This node's inner pool: the /24 around its descriptor router, or None.

    The descriptor is read with clock_tolerant=True, as the allocator reads it:
    a gateway keeps its inner address after the descriptor clock lapses, so
    the slice it serves from does not move at expiry. The signature is still
    verified in full. A node without a verified descriptor falls back to the
    envelope when the envelope is itself a single /24 (the legacy shared
    slice), and has no slice otherwise. A router outside the envelope has no
    slice: winn3_descriptor_missing_or_invalid already names it.
    """
    envelope = winn3_inner_pool()
    if envelope is None:
        return None
    decoded = winn3_stored_descriptor(node, clock_tolerant=True)
    router = str((decoded or {}).get("inner_router_v4") or "").strip()
    if router:
        try:
            node_pool = ipaddress.ip_network(router + "/24", strict=False)
        except ValueError:
            return None
        return node_pool if node_pool.subnet_of(envelope) else None
    return envelope if envelope.prefixlen == 24 else None

WINN3_IDENTITY_DIGEST_FIELDS = (
    "node", "endpoint", "static_pub", "gateway_id", "inner_router_v4",
    "inner_resolver_v4", "auth_ed25519", "auth_mldsa65",
)

def winn3_canonical(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")

def winn3_identity_digest(descriptor: dict) -> str:
    """H1 contract ruling: descriptor encodings, with the secret's fingerprint."""
    fields = {name: descriptor.get(name, "") for name in WINN3_IDENTITY_DIGEST_FIELDS}
    secret = base64.b64decode(descriptor["admission_secret"], validate=True).decode("ascii")
    if not re.fullmatch(r"[0-9a-f]{64}", secret):
        raise ValueError("admission-secret-malformed")
    fields["admission_fingerprint"] = hashlib.sha256(
        b"winn3-admission-fingerprint-v1" + secret.encode("ascii")).hexdigest()[:16]
    return hashlib.sha256(winn3_canonical(fields)).hexdigest()

def winn3_read_canary_key(path: Path) -> bytes:
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(fd, "rb") as stream:
        info = os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_mode & 0o077:
            raise ValueError("canary-key-unsafe")
        value = stream.read(129)
    if not re.fullmatch(b"[0-9a-f]{64}\\n?", value):
        raise ValueError("canary-key-malformed")
    return value.strip()

def winn3_write_canary_file(directory: Path, name: str, value: bytes) -> None:
    fd = os.open(directory, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    temporary = "." + name + "." + secrets.token_hex(16)
    try:
        target = os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW,
                         0o600, dir_fd=fd)
        with os.fdopen(target, "wb") as stream:
            stream.write(value)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, name, src_dir_fd=fd, dst_dir_fd=fd)
        os.fsync(fd)
    finally:
        try:
            os.unlink(temporary, dir_fd=fd)
        except FileNotFoundError:
            pass
        os.close(fd)

def winn3_render_canary_profile(node: Any) -> dict:
    """The descriptor and params serving render, without its circular freshness gate."""
    if strict_stored_protocol_version(node) != WINN_PROTOCOL_V3:
        raise ValueError("canary-carrier-not-winn3")
    params = validate_winn3_protocol_params(parse_protocol_params(_node_field(node, "protocol_params_json")))
    if params.get("carrier") != WINN3_CARRIER_WINN3 or winn3_params_require_spa(params):
        raise ValueError("canary-profile-not-standalone")
    envelope, reason = resolve_served_winn3_descriptor(
        node, capabilities={WINN3_DESCRIPTOR_CLIENT_CAPABILITY: True, WINN3_DUALAUTH_CLIENT_CAPABILITY: True},
        served_protocol_version=WINN_PROTOCOL_V3)
    if not envelope or reason != "winn3-descriptor":
        raise ValueError("canary-served-descriptor-invalid")
    descriptor = json.loads(base64.b64decode(envelope["payload"], validate=True))
    endpoint = params.get("gateway_endpoint") or _node_field(node, "endpoint")
    if endpoint != descriptor["endpoint"]:
        raise ValueError("canary-served-endpoint-mismatch")
    if not winn3_standalone_plan_for_node(node)[0] or winn3_gateway_report_blockers(node, descriptor):
        raise ValueError("canary-served-plan-or-report-invalid")
    return dict(descriptor, path_mtu=winn3_effective_path_mtu(node),
                carrier_classes=parse_winn3_carrier_classes(_node_field(node, "carrier_classes")))

WINN3_CANARY_PROBE_TIMEOUT_SECONDS = 60

def winn3_run_canary_probe(argv: list, timeout: float) -> subprocess.CompletedProcess:
    """Run one winn3-probe in a process group of its own. On a timeout the
    whole group is killed while the probe is still unreaped, so the group id
    cannot belong to another process yet, and only then is the probe reaped.
    subprocess.run(timeout=...) kills only the probe and leaves its children."""
    import signal
    proc = subprocess.Popen(argv, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                            stderr=subprocess.PIPE, start_new_session=True)
    try:
        stdout, stderr = proc.communicate(timeout=timeout)
    except subprocess.TimeoutExpired:
        if proc.returncode is None:
            try:
                os.killpg(proc.pid, signal.SIGKILL)
            except OSError:
                pass
        try:
            proc.communicate(timeout=10)
        except subprocess.TimeoutExpired:
            # Something that left the group still holds a pipe.
            proc.kill()
            for stream in (proc.stdout, proc.stderr):
                stream.close()
            proc.wait()
        raise
    return subprocess.CompletedProcess(argv, proc.returncode, stdout, stderr)

def winn3_probe_canary(profile: dict, binding: dict, generation: int, seq: Optional[int]) -> dict:
    proof = dict(status="fail", detail="canary-probe-failed", identity_sha256=winn3_identity_digest(profile),
                 generation=generation, checked_at=utcnow().isoformat(), handshake=False, carried=False, dns=False)
    if seq is not None:
        proof["seq"] = seq
    try:
        private = winn3_read_canary_key(Path(binding["key_dir"]) / "client.key")
        # Every invocation owns a snapshot. A concurrent renewal cannot change
        # the credentials that an in-flight probe tests.
        with tempfile.TemporaryDirectory() as work:
            directory = Path(work)
            os.chmod(directory, 0o700)
            files = {"client.key": private, "static.pub": base64.b64decode(profile["static_pub"], validate=True).hex().encode(),
                     "admission.key": base64.b64decode(profile["admission_secret"], validate=True)}
            for name, value in files.items():
                path = directory / name
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                with os.fdopen(fd, "wb") as stream:
                    stream.write(value)
            args = [os.getenv("WINN3_CANARY_BIN", "") or "/usr/local/bin/winn3-probe",
                    "-gw", profile["endpoint"], "-dir", str(directory), "-gateway-id",
                    base64.b64decode(profile["gateway_id"], validate=True).decode("utf-8"),
                    "-inner", binding["inner_v4"], "-path-mtu", str(profile["path_mtu"]),
                    "-dual-ed-pub", base64.b64decode(profile["auth_ed25519"], validate=True).hex(),
                    "-dual-ml-pub", base64.b64decode(profile["auth_mldsa65"], validate=True).hex(),
                    "-count", "1", "-interval", "100ms", "-budget", "10s"]
            for mode in ([], ["-dns", os.getenv("WINN3_CANARY_DNS_NAME", "cloudflare.com"),
                             "-dns-server", profile["inner_resolver_v4"]]):
                completed = winn3_run_canary_probe(args + mode, timeout=WINN3_CANARY_PROBE_TIMEOUT_SECONDS)
                if completed.returncode != 0 or b"HANDSHAKE ok state=carrying" not in completed.stdout:
                    return proof
                proof["handshake"] = True
                proof["dns" if mode else "carried"] = True
        proof.update(status="ok", detail="")
    except (OSError, ValueError, KeyError, subprocess.TimeoutExpired):
        pass
    finally:
        proof["checked_at"] = utcnow().isoformat()
    return proof

WINN3_GATEWAY_REPORT_STATES = ("active", "inactive", "failed", "absent", "unknown")

WINN3_GATEWAY_REPORT_PLAN_RE = re.compile(r"^(udp|tcp|tls)(,(udp|tcp|tls)){0,2}$")

WINN3_GATEWAY_REPORT_LISTEN_RE = re.compile(r"^[0-9A-Fa-f.:\[\]]{1,47}:[0-9]{1,5}$")

WINN3_GATEWAY_REPORT_ID_RE = re.compile(r"^[A-Za-z0-9._:-]{1,128}$")

WINN3_GATEWAY_REPORT_CIDR_RE = re.compile(r"^[0-9]{1,3}(\.[0-9]{1,3}){3}/[0-9]{1,2}$")

def sanitize_winn3_gateway_report(raw: Any) -> Optional[dict]:
    """The node's v3 gateway self-report, narrowed to known keys and shapes.

    Same standing as data_plane_code_revision: a node's claim about itself,
    accepted because it changes nothing that is served (no selection or serve
    path reads it) and lets the hub NAME a disagreement before a client meets
    it. None means "not reported". A field whose shape is wrong is kept as
    unknown ("" or None) rather than guessed.
    """
    if not isinstance(raw, dict):
        return None
    state = str(raw.get("state") or "").strip().lower()
    report: dict = {"state": state if state in WINN3_GATEWAY_REPORT_STATES else "unknown"}
    for key in ("forward", "resolver"):
        value = raw.get(key)
        report[key] = value if isinstance(value, bool) else None
    listen = str(raw.get("listen") or "").strip()
    report["listen"] = listen if WINN3_GATEWAY_REPORT_LISTEN_RE.match(listen) else ""
    gateway_id = str(raw.get("gateway_id") or "")
    report["gateway_id"] = gateway_id if WINN3_GATEWAY_REPORT_ID_RE.match(gateway_id) else ""
    inner = str(raw.get("inner_v4") or "").strip()
    report["inner_v4"] = inner if winn3_is_inner_ipv4(inner) else ""
    plan = str(raw.get("plan") or "").strip().lower()
    report["plan"] = plan if WINN3_GATEWAY_REPORT_PLAN_RE.match(plan) else ""
    cidr = str(raw.get("forward_cidr") or "").strip()
    report["forward_cidr"] = cidr if WINN3_GATEWAY_REPORT_CIDR_RE.match(cidr) else ""
    mtu = raw.get("path_mtu")
    report["path_mtu"] = (
        mtu if isinstance(mtu, int) and not isinstance(mtu, bool) and 576 <= mtu <= 65535 else None
    )
    # D5: whether the installed binary names peer-registry-tier in
    # `winn3-gateway -mode features`. The key is kept only when the node sent a
    # boolean, so a report from an older installer, a missing binary or a probe
    # that failed keeps exactly the shape it always had and publishes no tier.
    peer_tier = raw.get("peer_tier")
    if isinstance(peer_tier, bool):
        report["peer_tier"] = peer_tier
    return report

def parse_winn3_gateway_report(value: Any) -> Optional[dict]:
    """A stored report back as a dict, or None for missing or unreadable."""
    if not value:
        return None
    try:
        decoded = json.loads(value)
    except Exception:
        return None
    return sanitize_winn3_gateway_report(decoded)

# Root-owned CLI. The app database and bindings are data, never code.
from concurrent.futures import ThreadPoolExecutor
from contextlib import closing, contextmanager
import argparse
import errno
import math
import secrets
import sqlite3
import stat
import threading

CANARY_RESULT_DIR = Path('/var/lib/wins-canary-results')
CANARY_REQUEST_DIR = Path('/var/lib/wins-canary-requests')
CANARY_STATE_DIR = Path('/var/lib/wins-canary-dispatch')
# At most one run per slug per interval (design 3.11, 10.3 P-12).
CANARY_MIN_INTERVAL_SECONDS = 60
# While a request is held by that limit, the spool is listed again at least
# this often, so a request for another slug is not held behind it.
CANARY_HOLD_POLL_SECONDS = 5
# Fixed names beside slug-derived ones (<slug>.json in the spool, <slug>.lock
# and <slug>.last in the state directory). A leading dot never matches the
# slug pattern, so no node can be named like them.
CANARY_DISPATCH_LOCK = '.dispatch.lock'
CANARY_REJECTED_DIR = '.rejected'
_canary_local = threading.local()


@contextmanager
def get_db():
    yield _canary_local.connection


def open_canary_database(path):
    # Type=simple can start a dependent unit before the hub's startup hook
    # retains its WAL sidecars. Probe the schema, since connect alone is lazy.
    for attempt in range(41):
        connection = None
        try:
            connection = sqlite3.connect(Path(path).resolve().as_uri() + '?mode=ro', uri=True, timeout=30)
            connection.row_factory = sqlite3.Row
            connection.execute('PRAGMA query_only=ON')
            connection.execute('PRAGMA busy_timeout=0')
            connection.execute('SELECT 1 FROM sqlite_schema LIMIT 1').fetchall()
            connection.execute('PRAGMA busy_timeout=30000')
            return connection
        except sqlite3.OperationalError:
            if connection is not None:
                connection.close()
            if attempt == 40:
                raise
        except Exception:
            if connection is not None:
                connection.close()
            raise
        time.sleep(0.25)


def run_canary_slug(connection, slug):
    if not re.fullmatch(r'[a-z0-9][a-z0-9_-]{0,62}', slug):
        return False
    _canary_local.connection = connection
    row = connection.execute('SELECT * FROM nodes WHERE slug=?', (slug,)).fetchone()
    if row is None or dict(row).get('retired_at') or row['protocol_version'] != 'winn/3':
        return False
    # Capture a single SQLite snapshot before any subprocess. The result's
    # binding will be rejected if the row moves while the probe is running.
    connection.execute('BEGIN')
    try:
        row = connection.execute('SELECT * FROM nodes WHERE slug=?', (slug,)).fetchone()
        if (row is None or dict(row).get('retired_at') or row['protocol_version'] != 'winn/3'
                or dict(row).get('deployment_withdrawal_id') or not dict(row).get('deployment_released_at')):
            return False
        # Completion can leave a previous winn3 carrier in the row. Only a
        # flip committed after this deployment release is a live-profile run.
        if not row['winn3_carrier_flipped_at']:
            return False
        # The app's own parser, as in winn3_canary_is_fresh: an offset is
        # converted to UTC, a naive value is UTC, and a non-text marker (a
        # BLOB) or a malformed one is no proof.
        released = parse_iso_datetime(row['deployment_released_at'])
        flipped = parse_iso_datetime(row['winn3_carrier_flipped_at'])
        if released is None or flipped is None or flipped < released:
            return False
        profile = winn3_render_canary_profile(row)
        bindings, conflicts = winn3_canary_bindings()
        binding = bindings.get(slug)
        identity = winn3_identity_digest(profile)
        if not binding or slug in conflicts or row['winn3_identity_sha256'] != identity:
            return False
        generation = row['deployment_generation']
    finally:
        connection.rollback()
    if not claim_canary_slug(slug):
        # Refused only by the per-slug limit: the dispatcher holds the
        # request instead of dropping it.
        _canary_local.limited = True
        return False
    proof = winn3_probe_canary(profile, binding, generation, profile['seq'])
    result = {name: proof[name] for name in ('status', 'detail', 'identity_sha256', 'seq', 'generation')}
    result.update(slug=slug, checked_at=datetime.fromisoformat(proof['checked_at']).replace(tzinfo=timezone.utc).isoformat())
    winn3_write_canary_file(CANARY_RESULT_DIR, slug + '.json', winn3_canonical(result))
    # The app is root but receives this directory read-only in its mount
    # namespace. Group/other write is forbidden by the ingestion rule.
    os.chmod(CANARY_RESULT_DIR / (slug + '.json'), 0o644)
    return proof['status'] == 'ok'


def canary_limit_remaining(slug):
    """Seconds until the slug may run again; 0 when it may run now. The limit
    never fails open and never holds for the size of a clock jump: a stamp in
    the future (the clock moved back), or one that is not a finite number
    (nan and -inf parse as numbers), is reset to now and holds the slug for
    one full interval. A stamp that exists but cannot be read holds the slug
    for one interval without being rewritten, so a request waiting on it is
    held, never discarded."""
    stamp = CANARY_STATE_DIR / (slug + '.last')
    try:
        last = float(stamp.read_text())
    except FileNotFoundError:
        return 0.0
    except ValueError:
        last = None
    except OSError:
        logger.warning('Canary stamp for %s cannot be read; the slug is held', slug)
        return float(CANARY_MIN_INTERVAL_SECONDS)
    now = time.time()
    if last is None or not math.isfinite(last) or last > now:
        winn3_write_canary_file(CANARY_STATE_DIR, slug + '.last', str(now).encode())
        return float(CANARY_MIN_INTERVAL_SECONDS)
    return max(0.0, CANARY_MIN_INTERVAL_SECONDS - (now - last))


def claim_canary_slug(slug):
    import fcntl
    lock = os.open(CANARY_STATE_DIR / (slug + '.lock'), os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            return False
        if canary_limit_remaining(slug) > 0:
            return False
        winn3_write_canary_file(CANARY_STATE_DIR, slug + '.last', str(time.time()).encode())
        return True
    finally:
        os.close(lock)


CANARY_DISPATCH_PASSES = 3
CANARY_DISPATCH_WORKERS = 4


def discard_canary_entry(directory, name):
    """Remove one spool entry without reading it. An empty directory is
    removed. A directory that is not empty is renamed, unwalked, to a random
    name inside CANARY_REJECTED_DIR: out of the spool's request names, so it
    cannot hold one of the 64 places of a listing, and on the spool's own
    mount (the unit's ReadWritePaths and StateDirectory entries are separate
    mounts under ProtectSystem=strict, and rename(2) does not cross mounts)."""
    try:
        info = os.lstat(name, dir_fd=directory)
    except FileNotFoundError:
        return
    if not stat.S_ISDIR(info.st_mode):
        try:
            os.unlink(name, dir_fd=directory)
        except FileNotFoundError:
            pass
        return
    try:
        os.rmdir(name, dir_fd=directory)
        return
    except FileNotFoundError:
        return
    except OSError as exc:
        if exc.errno not in (errno.ENOTEMPTY, errno.EEXIST):
            raise
    try:
        os.mkdir(CANARY_REJECTED_DIR, 0o700, dir_fd=directory)
    except FileExistsError:
        pass
    rejected = os.open(CANARY_REJECTED_DIR, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=directory)
    try:
        os.rename(name, secrets.token_hex(16), src_dir_fd=directory, dst_dir_fd=rejected)
    finally:
        os.close(rejected)
    logger.warning('Canary request directory moved out of the spool')


def consume_canary_request(connection, directory, name, held=None):
    """Validate and unlink one spooled request. Returns the slug to probe, or
    None. A valid request that only the slug's limit refuses is not unlinked:
    it stays in the spool and (slug, seconds left) is appended to held."""
    try:
        fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=directory)
        with os.fdopen(fd, 'rb') as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_size > 256:
                discard_canary_entry(directory, name)
                return None
            request = json.loads(stream.read(257))
        slug = name[:-5]
        if request != {'slug': slug}:
            os.unlink(name, dir_fd=directory)
            return None
        row = connection.execute('SELECT retired_at FROM nodes WHERE slug=?', (slug,)).fetchone()
        if row is None or row['retired_at']:
            os.unlink(name, dir_fd=directory)
            return None
        if held is not None:
            remaining = canary_limit_remaining(slug)
            if remaining > 0:
                held.append((slug, remaining))
                return None
        os.unlink(name, dir_fd=directory)
        return slug
    except (OSError, ValueError, TypeError, KeyError):
        logger.warning('Canary request refused')
        # Consume malformed names so the path unit cannot spin.
        try:
            discard_canary_entry(directory, name)
        except OSError:
            pass
        return None


def run_dispatched_slug(connection, slug):
    """Run one consumed request. When only the slug's limit refused it (the
    periodic canary claimed the slug after the request was consumed), the
    request is written back and the slug returned, so it is held, not lost."""
    _canary_local.limited = False
    try:
        run_canary_slug(connection, slug)
    except (ValueError, OSError, Winn3ContractError):
        logger.warning('Canary profile refused for %s', slug)
    if not getattr(_canary_local, 'limited', False):
        return None
    try:
        winn3_write_canary_file(CANARY_REQUEST_DIR, slug + '.json', winn3_canonical({'slug': slug}))
    except OSError:
        logger.warning('Canary request for %s could not be held', slug)
        return None
    return slug


def run_dispatched_slugs(connection, database, slugs):
    # H3-PERF (bounded parallel probes): independent slugs wait on the network,
    # not the CPU. Each worker owns a read-only connection of its own.
    # Returns the slugs whose requests were written back to be held.
    if database is None or len(slugs) < 2:
        return [slug for slug in [run_dispatched_slug(connection, slug) for slug in slugs] if slug]

    def work(slug):
        try:
            with closing(open_canary_database(database)) as own:
                return run_dispatched_slug(own, slug)
        except sqlite3.Error:
            logger.warning('Canary database unavailable for %s', slug)
            return None

    with ThreadPoolExecutor(max_workers=min(CANARY_DISPATCH_WORKERS, len(slugs))) as pool:
        return [slug for slug in pool.map(work, slugs) if slug]


def dispatch_canary_requests(connection, database=None):
    import fcntl
    lock = os.open(CANARY_STATE_DIR / CANARY_DISPATCH_LOCK, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        os.close(lock)
        return
    directory = os.open(CANARY_REQUEST_DIR, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        # H3-PERF (lost wake-up): a request that lands while this run executes
        # would be seen by neither this run nor a second one, because the second
        # fails the lock. Look again before releasing it, a bounded number of times.
        # A request refused only by its slug's limit is held in the spool and
        # run when the limit ends, never dropped. The spool is listed again at
        # least every CANARY_HOLD_POLL_SECONDS meanwhile, and each request is
        # waited for at most one interval plus one poll from when this run
        # first held it; past that it stays in the spool for the next run.
        passes = 0
        first_held = {}
        while True:
            names = sorted(name for name in os.listdir(directory)
                           if re.fullmatch(r'[a-z0-9][a-z0-9_-]{0,62}\.json', name))[:64]
            held = []
            slugs = [slug for slug in (consume_canary_request(connection, directory, name, held)
                                       for name in names) if slug]
            progressed = len(names) > len(held)
            for slug in slugs:
                first_held.pop(slug, None)
            held.extend((slug, 0.0) for slug in run_dispatched_slugs(connection, database, slugs))
            if progressed:
                passes += 1
                if passes < CANARY_DISPATCH_PASSES:
                    continue
            now = time.monotonic()
            waits = []
            for slug, remaining in held:
                if now - first_held.setdefault(slug, now) < CANARY_MIN_INTERVAL_SECONDS + CANARY_HOLD_POLL_SECONDS:
                    waits.append(remaining)
                else:
                    logger.warning('Held canary request for %s left for the next run', slug)
            if not waits:
                break
            time.sleep(max(0.05, min(min(waits) + 0.2, CANARY_HOLD_POLL_SECONDS)))
    finally:
        os.close(directory)
        os.close(lock)


def require_root_canary_artifact(path):
    path = Path(path).resolve(strict=True)
    forbidden = ('/root/vpn_auth', '/var/lib/wins-hub-ssh', '/var/lib/wins-site-ai-tunnel',
                 '/var/lib/wins-security-alerts', '/var/lib/wins-canary-requests')
    if any(str(path) == root or str(path).startswith(root + '/') for root in forbidden):
        raise ValueError('canary-executable-is-app-writable')
    for item in (path, *path.parents):
        info = item.stat()
        if info.st_uid != 0 or info.st_gid != 0 or info.st_mode & 0o022:
            raise ValueError('canary-executable-is-not-root-owned')


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--database', required=True)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--slug')
    group.add_argument('--requests', action='store_true')
    args = parser.parse_args()
    require_root_canary_artifact(os.getenv('WINN3_CANARY_BIN', '') or '/usr/local/bin/winn3-probe')
    require_root_canary_artifact(__file__)
    with open_canary_database(args.database) as connection:
        if args.requests:
            dispatch_canary_requests(connection, args.database)
            return 0
        return 0 if run_canary_slug(connection, args.slug) else 1


if __name__ == '__main__':
    raise SystemExit(main())
